//! Evaluates arithmetic expressions. See SPEC.md.

use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Error {
    /// A character that can't start a token, at this byte offset.
    UnexpectedChar(usize),
    /// The input ended where an operand or a closing parenthesis was needed.
    UnexpectedEnd,
    /// A token that doesn't fit the grammar, at the byte offset where it starts.
    UnexpectedToken(usize),
    UnknownVariable(String),
    UnknownFunction(String),
    /// A function called with the wrong number of arguments: (name, given).
    Arity(String, usize),
    DivisionByZero,
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Tok {
    Num(f64, usize),
    Ident(String, usize),
    Op(char, usize), // + - * / % ^
    LParen(usize),
    RParen(usize),
    Comma(usize),
}

impl Tok {
    fn pos(&self) -> usize {
        match self {
            Tok::Num(_, p)
            | Tok::Ident(_, p)
            | Tok::Op(_, p)
            | Tok::LParen(p)
            | Tok::RParen(p)
            | Tok::Comma(p) => *p,
        }
    }
}

fn tokenize(src: &str) -> Result<Vec<Tok>, Error> {
    let b = src.as_bytes();
    let mut toks = Vec::new();
    let mut i = 0usize;
    while i < b.len() {
        match b[i] {
            b' ' | b'\t' | b'\n' | b'\r' => i += 1,
            b'(' => {
                toks.push(Tok::LParen(i));
                i += 1;
            }
            b')' => {
                toks.push(Tok::RParen(i));
                i += 1;
            }
            b',' => {
                toks.push(Tok::Comma(i));
                i += 1;
            }
            c if c == b'+' || c == b'-' || c == b'*' || c == b'/' || c == b'%' || c == b'^' => {
                toks.push(Tok::Op(c as char, i));
                i += 1;
            }
            b'.' if i + 1 < b.len() && b[i + 1].is_ascii_digit() => {
                // Number of the form `.5[exponent]`.
                let end = number_end(b, i);
                toks.push(Tok::Num(parse_num(b, i, end), i));
                i = end;
            }
            c if c.is_ascii_digit() => {
                let end = number_end(b, i);
                toks.push(Tok::Num(parse_num(b, i, end), i));
                i = end;
            }
            c if c.is_ascii_alphabetic() || c == b'_' => {
                let start = i;
                i += 1;
                while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                    i += 1;
                }
                let name = std::str::from_utf8(&b[start..i]).unwrap().to_string();
                toks.push(Tok::Ident(name, start));
            }
            _ => return Err(Error::UnexpectedChar(i)),
        }
    }
    Ok(toks)
}

/// Given a byte slice where a number starts at `start` (either a digit or a
/// `.` followed by a digit), return the index just past the end of the number.
fn number_end(b: &[u8], start: usize) -> usize {
    let mut i = start;
    if b[i] != b'.' {
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        // A fraction needs at least one digit after the dot.
        if i < b.len() && b[i] == b'.' && i + 1 < b.len() && b[i + 1].is_ascii_digit() {
            i += 1;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
        }
    } else {
        // `.digits`
        i += 1;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
    }
    // An exponent needs at least one digit (after an optional sign).
    if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
        let mut k = i + 1;
        if k < b.len() && (b[k] == b'+' || b[k] == b'-') {
            k += 1;
        }
        if k < b.len() && b[k].is_ascii_digit() {
            while k < b.len() && b[k].is_ascii_digit() {
                k += 1;
            }
            i = k;
        }
    }
    i
}

fn parse_num(b: &[u8], start: usize, end: usize) -> f64 {
    let s = std::str::from_utf8(&b[start..end]).unwrap();
    s.parse::<f64>().unwrap()
}

// ---------------------------------------------------------------------------
// Parser / evaluator
// ---------------------------------------------------------------------------

enum Expr {
    Num(f64),
    Var(String, usize),
    Add(Box<Expr>, Box<Expr>),
    Sub(Box<Expr>, Box<Expr>),
    Mul(Box<Expr>, Box<Expr>),
    Div(Box<Expr>, Box<Expr>),
    Mod(Box<Expr>, Box<Expr>),
    Pow(Box<Expr>, Box<Expr>),
    Neg(Box<Expr>),
    Pos(Box<Expr>),
    Call(String, usize, Vec<Expr>),
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn peek(&self) -> Option<&Tok> {
        self.toks.get(self.pos)
    }

    /// The token after the current one (used to tell function calls from
    /// variables).
    fn peek2(&self) -> Option<&Tok> {
        self.toks.get(self.pos + 1)
    }

    fn advance(&mut self) -> Option<Tok> {
        let t = self.toks.get(self.pos).cloned();
        if t.is_some() {
            self.pos += 1;
        }
        t
    }

    fn expect_rparen(&mut self) -> Result<(), Error> {
        match self.advance() {
            Some(Tok::RParen(_)) => Ok(()),
            None => Err(Error::UnexpectedEnd),
            Some(t) => Err(Error::UnexpectedToken(t.pos())),
        }
    }

    fn parse_args(&mut self) -> Result<Vec<Expr>, Error> {
        let mut args = Vec::new();
        if let Some(Tok::RParen(_)) = self.peek() {
            return Ok(args);
        }
        loop {
            args.push(self.parse_additive()?);
            match self.peek() {
                Some(Tok::Comma(_)) => {
                    self.advance();
                    continue;
                }
                _ => break,
            }
        }
        self.expect_rparen()?;
        Ok(args)
    }

    /// `+ -` binary, left associative (lowest precedence).
    fn parse_additive(&mut self) -> Result<Expr, Error> {
        let mut left = self.parse_multiplicative()?;
        while let Some(Tok::Op(op, _)) = self.peek() {
            match op {
                '+' | '-' => {
                    self.advance();
                    let right = self.parse_multiplicative()?;
                    left = if *op == '+' {
                        Expr::Add(Box::new(left), Box::new(right))
                    } else {
                        Expr::Sub(Box::new(left), Box::new(right))
                    };
                }
                _ => break,
            }
        }
        Ok(left)
    }

    /// `* / %` left associative.
    fn parse_multiplicative(&mut self) -> Result<Expr, Error> {
        let mut left = self.parse_unary()?;
        while let Some(Tok::Op(op, _)) = self.peek() {
            match op {
                '*' | '/' | '%' => {
                    self.advance();
                    let right = self.parse_unary()?;
                    left = match op {
                        '*' => Expr::Mul(Box::new(left), Box::new(right)),
                        '/' => Expr::Div(Box::new(left), Box::new(right)),
                        _ => Expr::Mod(Box::new(left), Box::new(right)),
                    };
                }
                _ => break,
            }
        }
        Ok(left)
    }

    /// Unary `+`/`-`, repeatable (`--2` is 2).
    fn parse_unary(&mut self) -> Result<Expr, Error> {
        if let Some(Tok::Op(op, _)) = self.peek() {
            if *op == '+' || *op == '-' {
                self.advance();
                let e = self.parse_unary()?;
                return Ok(if *op == '-' {
                    Expr::Neg(Box::new(e))
                } else {
                    Expr::Pos(Box::new(e))
                });
            }
        }
        self.parse_power()
    }

    /// `^`, right associative, binds tighter than unary minus.
    /// The exponent is a unary expression (`2^-1`).
    fn parse_power(&mut self) -> Result<Expr, Error> {
        let base = self.parse_primary()?;
        if let Some(Tok::Op('^', _)) = self.peek() {
            self.advance();
            let exp = self.parse_unary()?;
            Ok(Expr::Pow(Box::new(base), Box::new(exp)))
        } else {
            Ok(base)
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, Error> {
        match self.peek() {
            Some(Tok::Num(v, _)) => {
                self.advance();
                Ok(Expr::Num(*v))
            }
            Some(Tok::Ident(name, pos)) => {
                let is_call = matches!(self.peek2(), Some(Tok::LParen(_)));
                self.advance();
                if is_call {
                    self.advance(); // consume `(`
                    let args = self.parse_args()?;
                    Ok(Expr::Call(name.clone(), *pos, args))
                } else {
                    Ok(Expr::Var(name.clone(), *pos))
                }
            }
            Some(Tok::LParen(_)) => {
                self.advance();
                let e = self.parse_additive()?;
                self.expect_rparen()?;
                Ok(e)
            }
            Some(t) => Err(Error::UnexpectedToken(t.pos())),
            None => Err(Error::UnexpectedEnd),
        }
    }
}

fn eval_expr(e: &Expr, vars: &HashMap<String, f64>) -> Result<f64, Error> {
    match e {
        Expr::Num(v) => Ok(*v),
        Expr::Var(name, _) => vars
            .get(name)
            .copied()
            .ok_or(Error::UnknownVariable(name.clone())),
        Expr::Add(l, r) => Ok(eval_expr(l, vars)? + eval_expr(r, vars)?),
        Expr::Sub(l, r) => Ok(eval_expr(l, vars)? - eval_expr(r, vars)?),
        Expr::Mul(l, r) => Ok(eval_expr(l, vars)? * eval_expr(r, vars)?),
        Expr::Div(l, r) => {
            let d = eval_expr(r, vars)?;
            if d == 0.0 {
                return Err(Error::DivisionByZero);
            }
            Ok(eval_expr(l, vars)? / d)
        }
        Expr::Mod(l, r) => {
            let d = eval_expr(r, vars)?;
            if d == 0.0 {
                return Err(Error::DivisionByZero);
            }
            Ok(eval_expr(l, vars)? % d)
        }
        Expr::Pow(l, r) => Ok(eval_expr(l, vars)?.powf(eval_expr(r, vars)?)),
        Expr::Neg(e) => Ok(-eval_expr(e, vars)?),
        Expr::Pos(e) => Ok(eval_expr(e, vars)?),
        Expr::Call(name, _, args) => {
            let vals: Result<Vec<f64>, Error> =
                args.iter().map(|a| eval_expr(a, vars)).collect();
            call_fn(name, &vals?)
        }
    }
}

fn call_fn(name: &str, args: &[f64]) -> Result<f64, Error> {
    match name {
        "abs" => {
            if args.len() != 1 {
                return Err(Error::Arity("abs".into(), args.len()));
            }
            Ok(args[0].abs())
        }
        "sqrt" => {
            if args.len() != 1 {
                return Err(Error::Arity("sqrt".into(), args.len()));
            }
            Ok(args[0].sqrt())
        }
        "min" => {
            if args.is_empty() {
                return Err(Error::Arity("min".into(), 0));
            }
            let mut m = args[0];
            for &a in &args[1..] {
                m = m.min(a);
            }
            Ok(m)
        }
        "max" => {
            if args.is_empty() {
                return Err(Error::Arity("max".into(), 0));
            }
            let mut m = args[0];
            for &a in &args[1..] {
                m = m.max(a);
            }
            Ok(m)
        }
        _ => Err(Error::UnknownFunction(name.to_string())),
    }
}

pub fn eval(src: &str, vars: &HashMap<String, f64>) -> Result<f64, Error> {
    let toks = tokenize(src)?;
    let mut p = Parser { toks, pos: 0 };
    if p.peek().is_none() {
        return Err(Error::UnexpectedEnd);
    }
    let e = p.parse_additive()?;
    if let Some(t) = p.peek() {
        return Err(Error::UnexpectedToken(t.pos()));
    }
    eval_expr(&e, vars)
}

use calc::eval;
use std::collections::HashMap;

fn vars(pairs: &[(&str, f64)]) -> HashMap<String, f64> {
    pairs
        .iter()
        .map(|(k, v)| (k.to_string(), *v))
        .collect()
}

fn ok(src: &str, expected: f64) {
    let got = eval(src, &vars(&[])).unwrap_or_else(|e| panic!("{src:?} => Err({e:?}), expected {expected}"));
    assert!(
        (got - expected).abs() < 1e-12,
        "{src:?} => {got}, expected {expected}"
    );
}

fn okv(src: &str, expected: f64, v: &[(&str, f64)]) {
    let got = eval(src, &vars(v)).unwrap_or_else(|e| panic!("{src:?} => Err({e:?}), expected {expected}"));
    assert!(
        (got - expected).abs() < 1e-12,
        "{src:?} => {got}, expected {expected}"
    );
}

fn err(src: &str, expected: calc::Error) {
    match eval(src, &vars(&[])) {
        Err(e) => assert_eq!(e, expected, "error for {src:?}"),
        Ok(v) => panic!("{src:?} => Ok({v}), expected {expected:?}"),
    }
}

fn errv(src: &str, expected: calc::Error, v: &[(&str, f64)]) {
    match eval(src, &vars(v)) {
        Err(e) => assert_eq!(e, expected, "error for {src:?}"),
        Ok(val) => panic!("{src:?} => Ok({val}), expected {expected:?}"),
    }
}

// ---------------------------------------------------------------- numbers

#[test]
fn numbers() {
    ok("3", 3.0);
    ok("3.25", 3.25);
    ok(".5", 0.5);
    ok("2e3", 2000.0);
    ok("1.5E-2", 0.015);
    ok(".5e2", 50.0);
    ok("2e3 + 1", 2001.0);
    ok(".5 + .5", 1.0);
    // A number can't start with `e`: `e3` is an identifier.
    err("e3", calc::Error::UnknownVariable("e3".into()));
}

// ------------------------------------------------------------ unary / signs

#[test]
fn unary() {
    ok("+2", 2.0);
    ok("-2", -2.0);
    ok("--2", 2.0);
    ok("+-2", -2.0);
    ok("-+2", -2.0);
    ok("-(2 + 3)", -5.0);
    ok("2 * -3", -6.0);
    ok("1 - -2", 3.0);
    ok("1 - --2", -1.0);
    ok("2 * -3 ^ 2", -18.0);
}

// ------------------------------------------------------- precedence and ^

#[test]
fn precedence() {
    ok("1 + 2 * 3", 7.0);
    ok("10 - 4 / 2", 8.0);
    ok("(1 + 2) * 3", 9.0);
    ok("100 / 10 / 2", 5.0); // left associative
    ok("100 - 10 - 2", 88.0); // left associative
    ok("2 + 3 * 4 ^ 2", 50.0);
    ok("2 * 3 ^ 2", 18.0);
    ok("2 ^ 3 * 2", 16.0);
    ok("2 + 3", 5.0);
}

#[test]
fn power() {
    // `^` binds tighter than unary minus.
    ok("-2^2", -4.0);
    ok("(-2)^2", 4.0);
    // The exponent of `^` is a unary expression.
    ok("2^-1", 0.5);
    ok("2 ^ - 1", 0.5);
    ok("2^-1 * 4", 2.0);
    // `^` is right associative.
    ok("2^3^2", 512.0);
    ok("2^2^3", 16.0);
}

#[test]
fn remainder() {
    ok("10 % 3", 1.0);
    ok("10 % -3", 1.0); // sign of the dividend (Rust's f64 %)
    ok("-10 % 3", -1.0);
    ok("-10 % -3", -1.0);
    ok("2.5 % 2", 0.5);
    ok("10 / -2", -5.0);
    ok("2 % 4", 2.0);
}

// --------------------------------------------------------------- variables

#[test]
fn variables() {
    okv("x + 1", 6.0, &[("x", 5.0)]);
    okv("x * y - x", 14.0, &[("x", 2.0), ("y", 8.0)]);
    okv("_1", 1.0, &[("_1", 1.0)]);
    okv("x2 + x", 7.0, &[("x", 1.0), ("x2", 6.0)]);
    // A function name without `(` is just a variable.
    okv("abs", 9.0, &[("abs", 9.0)]);
    errv("abs", calc::Error::UnknownVariable("abs".into()), &[]);
}

// --------------------------------------------------------------- functions

#[test]
fn functions() {
    ok("abs(-5)", 5.0);
    ok("abs(3 - 10)", 7.0);
    ok("abs(0)", 0.0);
    ok("sqrt(16)", 4.0);
    ok("sqrt(2.0)", std::f64::consts::SQRT_2);
    ok("sqrt(abs(-16))", 4.0);
    ok("min(1, 2, 3)", 1.0);
    ok("min(5)", 5.0);
    ok("max(1, 5, 3)", 5.0);
    ok("max(3)", 3.0);
    ok("min(max(1, 2), 0)", 0.0);
    ok("abs(min(-1, 2))", 1.0);
    ok("min(1, 2) * max(3, 4)", 4.0);
    ok("min(1, 2) + 3", 4.0);
    // Whitespace is ignored, including between the name and `(`.
    ok("min ( 1 , 2 )", 1.0);
    ok("min(1,2)", 1.0);
}

// ------------------------------------------------------------------ errors

#[test]
fn unexpected_char() {
    err("2 $ 3", calc::Error::UnexpectedChar(2));
    err("$", calc::Error::UnexpectedChar(0));
    err("1 -", calc::Error::UnexpectedEnd); // `-` is fine, but see below
    err("3 . 2", calc::Error::UnexpectedChar(2));
    err("1.", calc::Error::UnexpectedChar(1));
    err(".", calc::Error::UnexpectedChar(0));
    err("2 @", calc::Error::UnexpectedChar(2));
    err("2 # 3", calc::Error::UnexpectedChar(2));
}

#[test]
fn unexpected_end() {
    err("", calc::Error::UnexpectedEnd);
    err("   ", calc::Error::UnexpectedEnd);
    err("2 +", calc::Error::UnexpectedEnd);
    err("(1", calc::Error::UnexpectedEnd);
    err("min(1,", calc::Error::UnexpectedEnd);
    err("min(", calc::Error::UnexpectedEnd);
    err("2 *", calc::Error::UnexpectedEnd);
    err("2 ^", calc::Error::UnexpectedEnd);
    err("2 ^ +", calc::Error::UnexpectedEnd);
    err("-", calc::Error::UnexpectedEnd);
    err("1 +", calc::Error::UnexpectedEnd);
    err("(1 +", calc::Error::UnexpectedEnd);
    err("2 / 0 +", calc::Error::UnexpectedEnd); // syntax error beats DivisionByZero
}

#[test]
fn unexpected_token() {
    err("2 3", calc::Error::UnexpectedToken(2));
    err(")", calc::Error::UnexpectedToken(0));
    err("(1))", calc::Error::UnexpectedToken(3));
    err("* 2", calc::Error::UnexpectedToken(0));
    err("()", calc::Error::UnexpectedToken(1));
    err("2 3", calc::Error::UnexpectedToken(2));
    err("1 / 0 y", calc::Error::UnexpectedToken(6)); // syntax error before eval
    err("2e", calc::Error::UnexpectedToken(1));
    err("1e+", calc::Error::UnexpectedToken(1));
}

#[test]
fn unknown_names() {
    err("foo", calc::Error::UnknownVariable("foo".into()));
    err("x", calc::Error::UnknownVariable("x".into()));
    err("foo(1)", calc::Error::UnknownFunction("foo".into()));
    err("foo(1, 2)", calc::Error::UnknownFunction("foo".into()));
}

#[test]
fn arity() {
    err("abs()", calc::Error::Arity("abs".into(), 0));
    err("abs(1, 2)", calc::Error::Arity("abs".into(), 2));
    err("sqrt()", calc::Error::Arity("sqrt".into(), 0));
    err("sqrt(1, 2)", calc::Error::Arity("sqrt".into(), 2));
    err("min()", calc::Error::Arity("min".into(), 0));
    err("max()", calc::Error::Arity("max".into(), 0));
}

#[test]
fn division_by_zero() {
    err("1 / 0", calc::Error::DivisionByZero);
    err("0 / 0", calc::Error::DivisionByZero);
    err("1 % 0", calc::Error::DivisionByZero);
    err("5 % 0", calc::Error::DivisionByZero);
    errv("x / 0", calc::Error::UnknownVariable("x".into()), &[]); // left operand first
    errv("1 / 0 + y", calc::Error::DivisionByZero, &[("y", 1.0)]);
}

// ------------------------------------------------- first error, left to right

#[test]
fn first_error_left_to_right() {
    err("1/0 + 1/0", calc::Error::DivisionByZero);
    errv("x + y", calc::Error::UnknownVariable("x".into()), &[("y", 1.0)]);
    // Syntax errors are found while parsing, so they win over later eval errors.
    err("1/0 x", calc::Error::UnexpectedToken(4));
    errv("x 1/0", calc::Error::UnexpectedToken(1), &[("x", 1.0)]);
}

